31	// validateGrantRole rejects unknown project/repo grant roles at the CLI
32	// boundary (reader, writer, admin) so the user gets a clear message instead of
33	// a server 422. The GrantProjectAccess and GrantRepoAccess input bodies use
34	// distinct enum types that share these values, so callers cast the validated
35	// string to whichever type they need.
36	func validateGrantRole(role string) error {
37		switch role {
38		case "reader", "writer", "admin":
39			return nil
40		default:
41			return fmt.Errorf("invalid --role %q: must be \"reader\", \"writer\", or \"admin\"", role)
42		}
43	}
