303	// revokeProjectGrantee revokes a grantee (provider:handle or account ULID) from
304	// a resolved project. A ULID grantee takes the typed-id route directly; a
305	// handle is resolved to its provider account first and takes the by-provider
306	// route. projectRef is the user's original (pre-resolution) project ref, used
307	// only for the success message.
308	func revokeProjectGrantee(ctx context.Context, cmd *cobra.Command, c *coreapi.Client, projID, projectRef, grantee string) error {
309		if looksLikeULID(grantee) {
310			return revokeGrant(cmd, "Revoked", fmt.Sprintf("account %s from project %s", grantee, projectRef), func() error {
311				return c.RevokeProjectAccess(ctx, coreapi.RevokeProjectAccessParams{
312					ProjectId:   projID,
313					GranteeType: "account",
314					GranteeId:   grantee,
315				})
316			})
317		}
318		provider, providerUserID, err := resolveGranteeProvider(ctx, c, grantee)
319		if err != nil {
320			return err
321		}
322		return revokeGrant(cmd, "Revoked", fmt.Sprintf("%s from project %s", grantee, projectRef), func() error {
323			return c.RevokeProjectAccessByProvider(ctx, coreapi.RevokeProjectAccessByProviderParams{
324				ProjectId:      projID,
