461	// revokeGrant runs a grant-removal API call idempotently. A 404 means the
462	// grantee already has no such grant — the desired end state — so it's reported
463	// as a no-op rather than surfaced as a raw error, matching runControlPlaneDelete.
464	// verb is the success word ("Revoked"/"Removed"); subject describes the grant,
465	// e.g. "github:alice from repo acme".
466	func revokeGrant(cmd *cobra.Command, verb, subject string, revoke func() error) error {
467		if err := revoke(); err != nil {
468			if isCoreNotFound(err) {
469				cmd.Printf("%s: no such grant; nothing to revoke\n", subject)
470				return nil
471			}
472			return err
473		}
474		cmd.Printf("%s %s\n", verb, subject)
475		return nil
476	}
